fn cf_body(id:u32)->Vec<u8>{let mut b=vec![207];b.extend(id.to_le_bytes());b}
fn cc_body(id:u32,name:&[u8],map:u16)->Vec<u8>{let mut b=vec![204,0];b.extend(id.to_le_bytes());b.extend(name);b.extend([0,0]);b.extend(1u16.to_le_bytes());b.extend(8u16.to_le_bytes());b.extend(map.to_le_bytes());b.push(1);b}
fn accept_bounded(listener:&TcpListener)->Result<TcpStream>{
 listener.set_nonblocking(true)?;let end=Instant::now()+Duration::from_secs(15);
 loop {match listener.accept(){Ok((s,_))=>{s.set_nonblocking(false)?;return Ok(s)},Err(e) if e.kind()==std::io::ErrorKind::WouldBlock=>{ensure!(Instant::now()<end,"owned producer accept deadline expired");thread::sleep(Duration::from_millis(2));},Err(e)=>return Err(e.into())}}
}
